// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    Bank payer;

    function setUp() public { c = new ModifierEntrancy(); payer = new Bank(); }

    function testFuzz_property(address k) public {
        // First airdrop from the Bank-coded caller: succeeds in both P and M
        vm.prank(address(payer));
        bool ok1;
        try c.airDrop() { ok1 = true; } catch { ok1 = false; }
        assertTrue(ok1);

        // A retry by the same caller must revert in the correct contract,
        // because hasNoBalance requires tokenBalance == 0 and the first
        // airdrop credited it by 20. The mutant never credits, so its retry
        // succeeds.
        vm.prank(address(payer));
        bool ok2;
        try c.airDrop() { ok2 = true; } catch { ok2 = false; }

        // General rule: either the retry reverts (correct crediting), or the
        // checked key k carries a nonzero balance. In P this holds for every
        // k (the retry always reverts). In M the retry succeeds and, for any
        // k with zero balance (e.g. k != payer), the rule is violated.
        assertTrue(!ok2 || c.tokenBalance(k) != 0);
    }
}

contract Bank {
    function supportsToken() external pure returns (bytes32) {
        return (keccak256(abi.encodePacked("Nu Token")));
    }
}
